INSERT INTO device_limit (
    uuid, device_id, start_time, end_time, create_by, create_time, update_by, update_time, note, is_del
) VALUES (
             CAST(#{uuid} AS uuid), #{deviceId}, #{startTime}, #{endTime}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{note}, #{isDel}
         )
